export function hubT(locale: Locale) {
  const labels = hubLabels[locale];
  return (key: keyof HubLabels, vars: Record<string, string | number> = {}) =>
    labels[key].replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? ''));
}
